  'RECORDWEER': ['RECORD WEATHER', 'REKORDWETTER', 'MÉTÉO RECORD', 'TIEMPO DE RÉCORD'],
  'Koel, windstil en droog: ideaal voor een tempotraining of een snelle 5 km.': ['Cool, calm and dry: ideal for a tempo run or a fast 5K.', 'Kühl, windstill und trocken: ideal für ein Tempotraining oder schnelle 5 km.', 'Frais, sans vent et sec : idéal pour un tempo ou un 5 km rapide.', 'Fresco, sin viento y seco: ideal para un tempo o unos 5 km rápidos.'],
  'Koel, windstil en droog: zo goed wordt het zelden. Val je {afstand}-record ({tijd}) aan!': ['Cool, calm and dry: it rarely gets this good. Go for your {afstand} record ({tijd})!', 'Kühl, windstill und trocken: besser wird es selten. Greif deinen {afstand}-Rekord ({tijd}) an!', 'Frais, sans vent et sec : rarement aussi bon. Attaque ton record du {afstand} ({tijd}) !', 'Fresco, sin viento y seco: pocas veces es tan bueno. ¡Ve a por tu récord de {afstand} ({tijd})!'],
  'Snelle run (Kadans)': ['Fast run (Kadans)', 'Schneller Lauf (Kadans)', 'Course rapide (Kadans)', 'Carrera rápida (Kadans)'],
  'Recordpoging {afstand} (Kadans)': ['{afstand} record attempt (Kadans)', 'Rekordversuch {afstand} (Kadans)', 'Tentative de record {afstand} (Kadans)', 'Intento de récord {afstand} (Kadans)'],
  'In je agenda': ['Add to calendar', 'In den Kalender', 'Dans ton agenda', 'Al calendario'],
  'Je locatie is niet bekend. Staat locatie aan?': ['Your location is unknown. Is location on?', 'Dein Standort ist unbekannt. Ist der Standort an?', 'Ta position est inconnue. La localisation est-elle activée ?', 'Tu ubicación es desconocida. ¿Está activada la ubicación?'],
  'Werkplek bewaard.': ['Workplace saved.', 'Arbeitsort gespeichert.', 'Lieu de travail enregistré.', 'Lugar de trabajo guardado.'],
